const $=id=>document.getElementById(id),data=[null,null],raw=[null,null];let results=[],filter='all',page=0;
function say(s){$('message').textContent=s;}
function invalidate(){$('results').hidden=true;$('empty').hidden=false;results=[];say('');}
function configure(){invalidate();const common=data.every(Boolean)?data[0].headers.filter(h=>data[1].headers.includes(h)):[];const old=$('key').value;$('key').replaceChildren();for(const h of common){const o=new Option(h,h);$('key').add(o);}if(common.includes(old))$('key').value=old;else if(common.includes('SKU'))$('key').value='SKU';$('key').disabled=!common.length;$('compare').disabled=!common.length;fields();if(data.every(Boolean)){const only0=data[0].headers.filter(h=>!common.includes(h)),only1=data[1].headers.filter(h=>!common.includes(h));$('schema').textContent=only0.length||only1.length?'Only shared columns are compared. Original-only: '+(only0.join(', ')||'none')+'. Updated-only: '+(only1.join(', ')||'none')+'.':'';if(!common.length)say('These files have no column headers in common.');}}
function fields(){$('fields').replaceChildren();if(!data.every(Boolean)){$('fields').textContent='Common columns appear here';return;}for(const h of data[0].headers.filter(h=>data[1].headers.includes(h)&&h!==$('key').value)){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=h;input.checked=true;input.addEventListener('change',invalidate);label.append(input,document.createTextNode(h));$('fields').append(label);}}
function setData(i,text,name){raw[i]={text,name};data[i]=null;try{data[i]=CSVCore.parse(text,$('delimiter').value==='tab'?'\t':$('delimiter').value);$('desc'+i).textContent=name;$('meta'+i).textContent=data[i].rows.length.toLocaleString()+' rows · '+data[i].headers.length+' columns';$('drop'+i).classList.add('loaded');configure();}catch(e){$('desc'+i).textContent=name;$('meta'+i).textContent='Could not read file';$('drop'+i).classList.remove('loaded');configure();say(e.message);}}
async function load(i,file){if(!file)return;if(file.size>10*1024*1024){say('Please choose a file smaller than 10 MB.');return;}try{const buffer=await file.arrayBuffer();const text=new TextDecoder('utf-8',{fatal:true}).decode(buffer);setData(i,text,file.name);}catch(e){say('Could not read this file as UTF-8. Export it as CSV UTF-8 and try again.');}}
for(let i=0;i<2;i++){$('file'+i).addEventListener('change',e=>load(i,e.target.files[0]));const el=$('drop'+i);el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drag');});el.addEventListener('dragleave',()=>el.classList.remove('drag'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drag');load(i,e.dataTransfer.files[0]);});}
$('delimiter').addEventListener('change',()=>{for(let i=0;i<2;i++)if(raw[i])setData(i,raw[i].text,raw[i].name);});$('key').addEventListener('change',()=>{invalidate();fields();});$('trim').addEventListener('change',invalidate);
$('demo').addEventListener('click',()=>{$('delimiter').value='';setData(0,'SKU,Product,Price,Stock\nLAMP-01,Studio lamp,49.00,12\nDESK-02,Oak desk,299.00,8\nCHAIR-03,Task chair,149.00,5\nSHELF-04,Wall shelf,39.00,20','original-demo.csv');setData(1,'SKU,Product,Price,Stock\nLAMP-01,Studio lamp,54.00,10\nDESK-02,Oak desk,299.00,8\nSHELF-04,Wall shelf,39.00,18\nTRAY-05,Desk tray,19.00,30','updated-demo.csv');run();});
function run(){say('');try{const selected=[...$('fields').querySelectorAll('input:checked')].map(x=>x.value);if(!selected.length)throw Error('Select at least one column to compare.');results=CSVCore.compare(data[0],data[1],$('key').value,selected,$('trim').checked);filter='all';page=0;$('search').value='';$('results').hidden=false;$('empty').hidden=true;const counts={changed:new Set(),added:new Set(),removed:new Set(),unchanged:new Set()};for(const r of results)counts[r.status].add(r.key);$('stats').replaceChildren();for(const [k,v] of Object.entries(counts)){const div=document.createElement('div');div.className='stat';const b=document.createElement('b');b.textContent=v.size.toLocaleString();const s=document.createElement('span');s.textContent=k[0].toUpperCase()+k.slice(1)+' records';div.append(b,s);$('stats').append(div);}render();}catch(e){invalidate();say(e.message);}}
$('compare').addEventListener('click',run);
function render(){const q=$('search').value.toLowerCase();const rows=results.filter(r=>(filter==='all'?r.status!=='unchanged':r.status===filter)&&(!q||(r.key+' '+r.field).toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(rows.length/50));page=Math.min(page,pages-1);$('body').replaceChildren();for(const r of rows.slice(page*50,page*50+50)){const tr=document.createElement('tr');for(const [i,value] of [r.status,r.key,r.field||'—',r.before,r.after].entries()){const td=document.createElement('td');if(i===0){const span=document.createElement('span');span.className='badge '+r.status;span.textContent=value;td.append(span);}else td.textContent=value;tr.append(td);}$('body').append(tr);}if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='No matching results. '+(filter==='all'?'Try the Unchanged tab to see matching records.':'');tr.append(td);$('body').append(tr);}$('count').textContent=rows.length.toLocaleString()+' report lines';$('page').textContent=(page+1)+' / '+pages;$('prev').disabled=page===0;$('next').disabled=page>=pages-1;for(const b of $('tabs').querySelectorAll('button')){b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter);}}
$('tabs').addEventListener('click',e=>{if(e.target.dataset.filter){filter=e.target.dataset.filter;page=0;render();}});$('search').addEventListener('input',()=>{page=0;render();});$('prev').addEventListener('click',()=>{page--;render();});$('next').addEventListener('click',()=>{page++;render();});
$('export').addEventListener('click',()=>{const text=CSVCore.csv([['Status','Record key','Column','Original value','Updated value'],...results.map(r=>[r.status,r.key,r.field,r.before,r.after])]);const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='csv-comparison-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('reset').addEventListener('click',()=>{for(let i=0;i<2;i++){data[i]=null;raw[i]=null;$('file'+i).value='';$('drop'+i).classList.remove('loaded');$('desc'+i).textContent=i?'The version you want to check':'Your earlier export or baseline';$('meta'+i).textContent='CSV · UTF-8 · up to 10 MB';}$('schema').textContent='';configure();});
